import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@3.3.0";
import { z as z2 } from "npm:zod@^3.25.76";
var list_estrategia_default = defineTool2({
  name: "list_estrategia",
  title: "Consultar OKRs e ciclos",
  description: "Consulta as OKRs estrat\xE9gicas e os ciclos de um ano para o usu\xE1rio aprovado, at\xE9 100 registros por grupo.",
  inputSchema: { ano: z2.number().int().min(1).max(9998).describe("Ano das OKRs e dos ciclos.") },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ ano }, ctx) => {
    const client = await supabaseForUser(ctx);
    const [okrs, ciclos] = await Promise.all([
      client.from("okrs_estrategicas").select("id,titulo,descricao,ano").eq("ano", ano).order("id").limit(100),
      client.from("ciclos").select("id,nome,tipo,numero,ano,data_inicio,data_fim").eq("ano", ano).order("numero").limit(100)
    ]);
    if (okrs.error || ciclos.error) return { isError: true, content: [{ type: "text", text: "N\xE3o foi poss\xEDvel consultar a estrat\xE9gia." }] };
    const result = { okrs: okrs.data ?? [], ciclos: ciclos.data ?? [] };
    return { content: [{ type: "text", text: JSON.stringify(result) }], structuredContent: result };
  }
});

